#!/usr/bin/env node
import {
  ExitCode,
  GramCLIError
} from "./chunk-IXNX2GX7.js";

// src/core/workspace.ts
import { access } from "fs/promises";
import { dirname, resolve } from "path";
async function searchProjectRoot(start) {
  let dir = start;
  while (true) {
    try {
      await access(resolve(dir, ".gram"));
      return dir;
    } catch {
    }
    const parent = dirname(dir);
    if (parent === dir) return null;
    dir = parent;
  }
}
async function findProjectRoot(start = process.cwd()) {
  return await searchProjectRoot(start) ?? start;
}
async function requireProjectRoot(start = process.cwd()) {
  const root = await searchProjectRoot(start);
  if (root === null) {
    throw new GramCLIError(
      "No gram project found in this directory or any parent. Run `gram init` to create one.",
      ExitCode.Error
    );
  }
  return root;
}

export {
  findProjectRoot,
  requireProjectRoot
};
